import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    system = platform.system()

    def _cpu_usage_once():
        if system == "Windows":
            out = subprocess.check_output(
                ["typeperf", r"\Processor(_Total)\% Processor Time", "-sc", "1"],
                stderr=subprocess.STDOUT
            ).decode(errors="ignore")
            lines = [ln.strip() for ln in out.splitlines() if ln.strip()]
            data_lines = [ln for ln in lines if ln.startswith('"') and '","' in ln]
            if not data_lines:
                raise ValueError("Unable to parse CPU usage output")
            last = data_lines[-1]
            parts = [p.strip().strip('"') for p in last.split('","')]
            val_str = parts[-1].replace(",", ".")
            return float(val_str)
        else:
            try:
                out = subprocess.check_output(
                    ["mpstat", "1", "1"],
                    stderr=subprocess.STDOUT
                ).decode(errors="ignore")
                lines = [ln.strip() for ln in out.splitlines() if ln.strip()]
                target = None
                for ln in reversed(lines):
                    low = ln.lower()
                    if low.startswith("average:"):
                        target = ln
                        break
                    toks = ln.split()
                    if toks and toks[-1].replace(".", "", 1).isdigit() and ("all" in toks or toks[0].isdigit()):
                        if "all" in toks:
                            target = ln
                            break
                if target is None:
                    raise ValueError("Unable to parse mpstat output")
                toks = target.split()
                idle_str = toks[-1].replace(",", ".")
                idle = float(idle_str)
                usage = 100.0 - idle
                if usage < 0:
                    usage = 0.0
                if usage > 100:
                    usage = 100.0
                return usage
            except Exception:
                if system == "Darwin":
                    out = subprocess.check_output(
                        ["top", "-l", "1", "-n", "0"],
                        stderr=subprocess.STDOUT
                    ).decode(errors="ignore")
                    for ln in out.splitlines():
                        if "CPU usage:" in ln:
                            frag = ln.split("CPU usage:", 1)[1].strip()
                            parts = [p.strip() for p in frag.split(",")]
                            user = 0.0
                            sysv = 0.0
                            for p in parts:
                                if "% user" in p:
                                    user = float(p.split("%", 1)[0].strip().replace(",", "."))
                                elif "% sys" in p:
                                    sysv = float(p.split("%", 1)[0].strip().replace(",", "."))
                            usage = user + sysv
                            if usage < 0:
                                usage = 0.0
                            if usage > 100:
                                usage = 100.0
                            return usage
                    raise ValueError("Unable to parse top output")
                else:
                    out = subprocess.check_output(
                        ["top", "-bn1"],
                        stderr=subprocess.STDOUT
                    ).decode(errors="ignore")
                    for ln in out.splitlines():
                        if "Cpu(s):" in ln or "%Cpu(s):" in ln:
                            right = ln.split(":", 1)[1]
                            tokens = [t.strip() for t in right.split(",")]
                            idle = None
                            for t in tokens:
                                if t.endswith(" id") or t.endswith("id"):
                                    num = t.split()[0].replace(",", ".")
                                    idle = float(num)
                                    break
                            if idle is None:
                                raise ValueError("Unable to parse top output")
                            usage = 100.0 - idle
                            if usage < 0:
                                usage = 0.0
                            if usage > 100:
                                usage = 100.0
                            return usage
                    raise ValueError("Unable to parse top output")

    records = []
    start = time.time()
    while True:
        now = time.time()
        if now - start >= duration:
            break
        usage = _cpu_usage_once()
        records.append({"timestamp": now, "cpu_usage": usage})
        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as f:
            json.dump(records, f)
        return LOGFILE_PATH
    except (OSError, IOError):
        return None
