import subprocess
import psutil
import time
import os

def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if script_path == "":
        raise ValueError("script_path must not be empty")
    if not isinstance(timeout, (int, float)):
        raise TypeError("timeout must be a number")
    if timeout <= 0:
        raise ValueError("timeout must be positive")
    if not os.path.exists(script_path):
        raise FileNotFoundError(script_path)

    p = subprocess.Popen(["bash", script_path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    cpu_usage = 0.0
    mem_usage = 0

    start_time = time.time()
    try:
        proc = psutil.Process(p.pid)
    except psutil.Error:
        proc = None

    last_rss = None
    if proc is not None:
        try:
            proc.cpu_percent(None)
            last_rss = proc.memory_info().rss
        except psutil.Error:
            proc = None

    interval = 0.1

    while True:
        if p.poll() is not None:
            break

        if time.time() - start_time >= timeout:
            try:
                p.terminate()
            except Exception:
                pass
            try:
                p.wait(timeout=1)
            except Exception:
                try:
                    p.kill()
                except Exception:
                    pass
            break

        if proc is None:
            time.sleep(interval)
            continue

        try:
            status = proc.status()
            if status == psutil.STATUS_ZOMBIE:
                break

            cpu_usage += float(proc.cpu_percent(None))

            rss = proc.memory_info().rss
            if last_rss is None:
                last_rss = rss
            else:
                if rss > last_rss:
                    mem_usage += int(rss - last_rss)
                last_rss = rss
        except (psutil.NoSuchProcess, psutil.ZombieProcess, psutil.AccessDenied):
            break

        time.sleep(interval)

    return {"CPU Usage": cpu_usage, "Memory Usage": mem_usage}
